<?php
declare(strict_types=1);
require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../config/db.php';require_once __DIR__.'/../../includes/report_tools.php';
$from=(string)($_GET['from']??date('Y-m-d',strtotime('-29 days')));$to=(string)($_GET['to']??date('Y-m-d'));$valid='/^\\d{4}-\\d{2}-\\d{2}$/';
if(!preg_match($valid,$from))$from=date('Y-m-d',strtotime('-29 days'));if(!preg_match($valid,$to))$to=date('Y-m-d');if($from>$to){[$from,$to]=[$to,$from];}
$startDate=new DateTimeImmutable($from);$endDate=new DateTimeImmutable($to);$span=(int)$startDate->diff($endDate)->days;
if($span>364){$from=$endDate->modify('-364 days')->format('Y-m-d');$startDate=new DateTimeImmutable($from);$span=364;}
$days=[];$values=[];$costs=[];
for($i=0;$i<=$span;$i++){$d=$startDate->modify("+$i days")->format('Y-m-d');$days[]=$d;$q=$conn->prepare("SELECT COALESCE(SUM(total_amount),0) FROM sales WHERE sale_status='Completed' AND DATE(sale_date)=?");$q->execute([$d]);$values[]=(float)$q->fetchColumn();$q=$conn->prepare("SELECT COALESCE(SUM(si.quantity*si.buying_price),0) FROM sale_items si JOIN sales s ON s.id=si.sale_id WHERE s.sale_status='Completed' AND DATE(s.sale_date)=?");$q->execute([$d]);$costs[]=(float)$q->fetchColumn();}
$q=$conn->prepare("SELECT p.product_name,SUM(si.quantity) qty,SUM(si.subtotal) revenue FROM sale_items si JOIN sales s ON s.id=si.sale_id JOIN products p ON p.id=si.product_id WHERE s.sale_status='Completed' AND DATE(s.sale_date) BETWEEN ? AND ? GROUP BY p.id ORDER BY revenue DESC LIMIT 10");$q->execute([$from,$to]);$top=$q->fetchAll();$max=max($values?:[1]);$maxTop=0;foreach($top as $t)$maxTop=max($maxTop,(float)$t['revenue']);
$exportRows=[];foreach($days as $i=>$day){$exportRows[]=['Daily Sales',$day,$values[$i],$costs[$i],$values[$i]-$costs[$i]];}foreach($top as $t){$exportRows[]=['Top Product',$t['product_name'],$t['qty'],$t['revenue'],''];}dibonkeReportExport('analytics_'.$from.'_to_'.$to,['Section','Date / Product','Revenue / Units','Cost','Gross Margin'],$exportRows);
require_once __DIR__.'/../../includes/header.php';require_once __DIR__.'/../../includes/sidebar.php';?>
<main class="content"><?php dibonkeReportPrintStyles(); ?><style>.analytics-filter{display:flex;gap:10px;align-items:end;flex-wrap:wrap;margin:12px 0}.analytics-filter label{font-size:12px;font-weight:700}.analytics-filter input{display:block;padding:9px;border:1px solid #cbd5e1;border-radius:7px}.btn{padding:9px 14px;background:#174a7e;color:#fff;border:0;border-radius:7px;font-weight:700}.panel{background:#fff;padding:20px;border-radius:12px;box-shadow:0 1px 4px #0001;margin-bottom:18px}.chart{height:300px;display:flex;align-items:end;gap:4px;border-bottom:1px solid #cbd5e1;padding:10px 0;overflow:hidden}.bar{flex:1;min-width:5px;background:#004a99;position:relative}.rows{display:grid;gap:10px}.row{display:grid;grid-template-columns:180px 1fr 120px;gap:10px;align-items:center}.track{height:16px;background:#e2e8f0;border-radius:10px;overflow:hidden}.fill{height:100%;background:#047857}@media(max-width:700px){.row{grid-template-columns:1fr}.chart{height:220px}}</style>
<h1>Analytics</h1><p>Sales trends and top products for the selected period.</p><form class="analytics-filter" method="get"><label>From <input type="date" name="from" value="<?=e($from)?>"></label><label>To <input type="date" name="to" value="<?=e($to)?>"></label><button class="btn">Run Analytics</button></form><?php dibonkeReportActions('analytics'); ?><div class="panel"><h3>Daily Sales Revenue</h3><div class="chart"><?php foreach($values as $i=>$v):?><div class="bar" style="height:<?=max(2,($v/$max)*100)?>%" title="<?=e($days[$i])?>: KES <?=number_format($v,2)?>"></div><?php endforeach;?></div><p style="color:#64748b;font-size:12px">Each bar represents one day, oldest to newest.</p></div>
<div class="panel"><h3>Top Products — Last 30 Days</h3><div class="rows"><?php foreach($top as $t):?><div class="row"><strong><?=e($t['product_name'])?></strong><div class="track"><div class="fill" style="width:<?=max(1,((float)$t['revenue']/$maxTop)*100)?>%"></div></div><span>KES <?=number_format((float)$t['revenue'],2)?></span></div><?php endforeach;?></div></div></main>
<?php require_once __DIR__.'/../../includes/footer.php';?>